query:
SELECT (STRAFTER(STR(?entity), "/entity/") AS ?item) ?label ?description ?formula
WHERE {
  VALUES ?entity { wd:Q103223 wd:Q108212 wd:Q108694 wd:Q1096 wd:Q111044 wd:Q11427 wd:Q1235463 wd:Q163577 wd:Q164411 wd:Q181395 wd:Q189703 wd:Q191222 wd:Q192669 wd:Q193565 wd:Q23757 wd:Q278106 wd:Q34095 wd:Q407335 wd:Q41177 wd:Q5283 wd:Q583353 wd:Q753 wd:Q83087 wd:Q860451 }
  OPTIONAL { ?entity rdfs:label ?label . FILTER(LANG(?label) = "en") }
  OPTIONAL { ?entity schema:description ?description . FILTER(LANG(?description) = "en") }
  OPTIONAL { ?entity wdt:P274 ?formula }
}
ORDER BY ?item ?formula
